/* ================= 2 · RECOVERY AT HOME ================= */
const R_GLOVE=(n)=>({k:'gloves',g:'wound',n:['Disposable gloves for dressing changes','Glavu za kutupwa za kubadilisha bandeji'],f:'m',q:[n+' a month','Glavu '+n+' kwa mwezi'],src:['who_hh','nice_ssi'],
 exp:['Clean gloves and washed hands are the barrier between the household and an open surgical wound, where most home infections start. Each dressing change uses one pair, plus a spare pair if the first tears or touches something unclean. '+(n===50?'At up to daily changes and cleaning in the first two weeks, 50 gloves cover the period.':'With changes every two to three days in weeks 3–6, 20 gloves are enough.')+' Nitrile is offered for latex allergy.',
     'Glavu safi na mikono iliyonawa ndizo kizuizi kati ya familia na jeraha la upasuaji lililo wazi, mahali ambapo maambukizi mengi ya nyumbani huanzia. Kila kubadilisha bandeji hutumia jozi moja, pamoja na jozi ya akiba ikichanika au kugusa kitu kichafu. '+(n===50?'Kwa kubadilisha hadi kila siku katika wiki mbili za kwanza, glavu 50 zinatosha.':'Kwa kubadilisha kila siku 2–3 katika wiki ya 3–6, glavu 20 zinatosha.')+' Glavu za nitrile zipo kwa wenye mzio wa mpira.'],
 o:{E:[[['sn_glv_l',n]],[['sn_glv_p',n]]],C:[[['sn_glv_n',n]]],L:[[['sn_glv_n',n]]]}});
const R_DRESS=(n)=>({k:'dress',g:'wound',n:['Sterile adhesive island dressings','Bandeji tasa zinazojibandika'],f:'m',q:[n+' dressings · '+(n===7?'changed every 2 days':'changed every 3–4 days'),'Bandeji '+n+' · '+(n===7?'kubadilishwa kila siku 2':'kubadilishwa kila siku 3–4')],src:['nice_ssi'],
 exp:['NICE advises covering a surgical incision with an interactive dressing and leaving it undisturbed unless it leaks, is soiled or the clinic says otherwise, because every unnecessary change exposes the wound. An island dressing has a non-stick pad and its own adhesive border, so no extra tape touches the wound edge. '+(n===7?'Changing about every two days gives 7 for the first two weeks, with spares for leaks.':'As the wound closes, a change every 3–4 days needs only 4 more.')+' Comfort moves to Primapore, the dressing most Tanzanian theatres use.'+' Luxury uses Opsite Post-Op showerproof dressings, so the person can shower without lifting them.',
     'NICE inashauri kufunika jeraha la upasuaji kwa bandeji maalum na kuiacha bila kuisumbua isipokuwa ivuje, ichafuke au kliniki iagize vinginevyo, kwa sababu kila kubadilisha kusiko lazima huliweka jeraha wazi. Bandeji ya aina hii ina pedi isiyonata na kingo zake za gundi, hivyo hakuna plasta ya ziada inayogusa ukingo wa jeraha. '+(n===7?'Kubadilisha takriban kila siku mbili ni bandeji 7 kwa wiki mbili za kwanza, pamoja na akiba.':'Jeraha linapofunga, kubadilisha kila siku 3–4 kunahitaji bandeji 4 tu zaidi.')+' Comfort hutumia Primapore, bandeji inayotumika katika vyumba vingi vya upasuaji nchini.'+' Toleo la Anasa linatumia bandeji za Opsite Post-Op zisizopitisha maji, hivyo mtu anaweza kuoga bila kuziondoa.'],
 o:{E:[[['sn_cura',n]],[['sn_prim',n]]],C:[[['sn_prim',n]]],L:[[['sn_opp',n]],[['sn_prim',n]]]}});
const R_GAUZE=(n)=>({k:'gauze',g:'wound',n:['Sterile gauze swabs','Pamba tasa ya shashi'],f:'m',q:[n+' swabs','Vipande '+n],src:['nice_ssi'],
 exp:['Sterile gauze is used to clean around the wound with saline, front to back, one swab per stroke, and as padding under a dressing where a drain or pin site oozes. '+(n===30?'At three to four swabs per change for about eight changes, 30 cover the first two weeks.':'With fewer changes in weeks 3–6, 20 swabs are enough.')+' Cotton wool is deliberately not used on wounds because its fibres stick and stay in the wound.'+' Sterile gauze is the same in every edition: it is a plain medical-grade product with no branded advantage.',
     'Shashi tasa hutumika kusafisha kuzunguka jeraha kwa maji ya chumvi, kutoka juu kwenda chini, kipande kimoja kwa kila mpigo, na kama kinga chini ya bandeji pale bomba au pini inapotoa majimaji. '+(n===30?'Kwa vipande 3–4 kila kubadilisha kwa mara takriban nane, vipande 30 vinatosha wiki mbili za kwanza.':'Kwa kubadilisha mara chache katika wiki ya 3–6, vipande 20 vinatosha.')+' Pamba ya kawaida haitumiki kwenye majeraha kwa makusudi kwa sababu nyuzi zake hunata na kubaki ndani ya jeraha.'+' Shashi tasa ni sawa katika kila toleo: ni bidhaa ya kawaida ya kitabibu isiyo na faida ya chapa yoyote.'],
 o:{E:[[['sn_gz',n]],[['sn_pad_s',n]]],C:[[['sn_gz',n]]],L:[[['sn_gz',n]]]}});
const R_PARA=(n)=>({k:'para',g:'pain',n:['Paracetamol 500 mg','Paracetamol miligramu 500'],f:'m',q:[n+' tablets','Vidonge '+n],src:['nhs_para'],
 exp:['Regular paracetamol is the safe first step for post-operative and fracture pain at home and lets people move, cough and sleep, which recovery depends on. The adult dose is two 500 mg tablets up to four times a day, never more than eight in 24 hours, with at least four hours between doses. '+(n===100?'Taken regularly through the first two weeks, that is about 100 tablets.':'In weeks 3–6 pain is usually only around exercise, so 50 tablets are planned.')+' Codeine combinations and anti-inflammatories are left out: they need a doctor’s advice after surgery, bleeding or a stroke. Check the discharge sheet so paracetamol is not doubled with another product.'+' Comfort and Luxury both use Panadol Advance: the medicine is identical, so Luxury does not charge more for the same tablet.',
     'Paracetamol ya mara kwa mara ndiyo hatua ya kwanza salama kwa maumivu ya baada ya upasuaji au kuvunjika nyumbani, na humwezesha mtu kutembea, kukohoa na kulala, mambo ambayo kupona hutegemea. Dozi ya mtu mzima ni vidonge viwili vya mg 500 hadi mara nne kwa siku, kamwe si zaidi ya vidonge vinane kwa saa 24, na angalau saa nne kati ya dozi. '+(n===100?'Ikitumika mara kwa mara wiki mbili za kwanza, ni takriban vidonge 100.':'Katika wiki ya 3–6 maumivu huwa wakati wa mazoezi tu, hivyo vidonge 50 vimepangwa.')+' Dawa zenye codeine na za kupunguza uvimbe hazijawekwa: zinahitaji ushauri wa daktari baada ya upasuaji, kutokwa damu au kiharusi. Angalia karatasi ya kuruhusiwa hospitali ili paracetamol isirudiwe kwenye dawa nyingine.'+' Faraja na Anasa zote hutumia Panadol Advance: dawa ni ile ile, hivyo Anasa haitozi zaidi kwa kidonge kile kile.'],
 o:{E:[[['sn_par_c',n]],[['sn_par_r',n]]],C:[[['fa_pa100',n]],[['sn_par_c',n]]],L:[[['fa_pa100',n]],[['sn_par_p',n]]]}});
const R_RUB=(f)=>({k:'rub',g:'wound',n:['Alcohol hand rub','Kitakasa mikono chenye alkoholi'],f:f,q:f==='m'?['1 bottle (500 ml)','Chupa 1 (ml 500)']:['1 bottle for weeks 3–6','Chupa 1 kwa wiki ya 3–6'],src:['who_hh','nice_ssi'],
 exp:['Hands are cleaned immediately before and after touching the wound or dressing, and before handling medicines; alcohol rub does this at the bedside in 20 seconds and is the WHO standard. About 3 ml per use, several times a day, means one 500 ml bottle covers the period. Soap and water is still used when hands are visibly dirty.',
     'Mikono husafishwa mara moja kabla na baada ya kugusa jeraha au bandeji, na kabla ya kushika dawa; kitakasa chenye alkoholi hufanya hivyo palepale kitandani kwa sekunde 20 na ndicho kiwango cha WHO. Takriban ml 3 kila mara, mara kadhaa kwa siku, humaanisha chupa ya ml 500 inatosha kipindi chote. Sabuni na maji bado hutumika mikono ikiwa michafu kwa kuonekana.'],
 o:{E:[[['sn_hr_l',525]],[['sn_hr_g',500]]],C:[[['sn_hr_s',500]]],L:[[['sn_hr_sa',500]],[['sn_hr_s',500]]]}});

const R_REP={k:'rep',g:'care',n:['Mosquito repellent','Dawa ya kufukuza mbu'],f:'m',q:['1 roll-on or bottle','Kopo au chupa 1'],src:['itn'],
 exp:['Long hours resting on a sofa or bed, often by an open window for air, leave a recovering person exposed to evening malaria mosquitoes and to day-biting dengue mosquitoes. Malaria after surgery, a fracture or a stroke causes a fever that is easily taken for wound infection and delays the right treatment. Repellent on exposed arms, legs and feet from late afternoon, kept well away from the wound and dressing, together with a treated net at night, closes that gap. One roll-on or bottle lasts about a month of daily use.',
     'Saa nyingi za kupumzika kwenye kochi au kitanda, mara nyingi karibu na dirisha lililo wazi, humweka anayepona hatarini kuumwa na mbu wa malaria jioni na mbu wa dengue wanaouma mchana. Malaria baada ya upasuaji, kuvunjika au kiharusi huleta homa inayoweza kudhaniwa kuwa maambukizi ya jeraha na kuchelewesha matibabu sahihi. Dawa ya kupaka kwenye mikono, miguu na nyayo zilizo wazi kuanzia alasiri, mbali kabisa na jeraha na bandeji, pamoja na chandarua chenye dawa usiku, hufunga pengo hilo. Kopo au chupa moja hudumu takriban mwezi kwa matumizi ya kila siku.'],
 o:{E:[[['rp_odo',1]],[['rp_bal',1]]],C:[[['rp_nob',1]],[['rp_odo',1]]],L:[[['rp_pea',1]],[['rp_nob',1]]]}};

const rec={
 key:'rec',
 name:['Recovery at home','Kupona nyumbani'],
 tagline:['Home from hospital, with everything the next six weeks require.','Umerudi kutoka hospitali, na kila kitu cha wiki sita zijazo.'],
 lede:['After surgery, a fracture or a stroke, the weeks at home decide how well and how fast a person recovers. This box brings sterile wound care, safe pain relief and the right walking aid in the first fortnight, then rehabilitation, circulation and nutrition support as strength returns.',
       'Baada ya upasuaji, kuvunjika au kiharusi, wiki za nyumbani ndizo huamua mtu atapona vizuri na kwa haraka kiasi gani. Sanduku hili huleta huduma tasa ya jeraha, dawa salama ya maumivu na kifaa sahihi cha kutembelea katika wiki mbili za kwanza, kisha mazoezi ya kurejesha nguvu, mzunguko wa damu na lishe kadiri nguvu zinavyorudi.'],
 stageWord:['Stage','Hatua'],
 boxes:[{k:'pt',n:['The recovery box','Sanduku la kupona'],g:['wound','pain','mob','rehab','nutri','care','zawadi']}],
 grp:{wound:['Wound care','Huduma ya jeraha'],pain:['Pain relief','Kupunguza maumivu'],mob:['Mobility & safety','Kutembea na usalama'],rehab:['Rehabilitation','Mazoezi ya kurejesha nguvu'],nutri:['Nutrition','Lishe'],care:['Personal care','Usafi binafsi'],zawadi:['The gift','Zawadi']},
 catalog:CAT, refs:REF,
 stages:[
  {k:'weeks1-2',n:['Weeks 1–2','Wiki 1–2'],d:['Wound care and first steps','Huduma ya jeraha na hatua za kwanza'],m:1,
   intro:['The first two weeks after discharge carry the highest risk of wound infection, falls and re-admission. NICE surgical-site guidance asks for sterile saline to clean the wound in the first 48 hours, a dressing left undisturbed unless it leaks, and hand hygiene before every touch. People leaving hospital after a fracture or stroke also need the right walking aid from day one, because the first fall at home is the commonest setback. WHO estimates 2.4 billion people need rehabilitation, with the largest unmet need in low-income countries.',
          'Wiki mbili za kwanza baada ya kuruhusiwa hospitali ndizo zenye hatari kubwa zaidi ya maambukizi ya jeraha, kuanguka na kurudi hospitali. Mwongozo wa NICE juu ya majeraha ya upasuaji unataka maji tasa ya chumvi kusafishia jeraha katika saa 48 za kwanza, bandeji iachwe bila kusumbuliwa isipokuwa ivuje, na kunawa mikono kabla ya kila mguso. Wanaotoka hospitali baada ya kuvunjika au kiharusi pia wanahitaji kifaa sahihi cha kutembelea tangu siku ya kwanza, kwa sababu kuanguka nyumbani ndiko kurudi nyuma kwa kawaida zaidi. WHO inakadiria watu bilioni 2.4 wanahitaji huduma ya kurejesha uwezo, na pengo kubwa zaidi liko katika nchi za kipato cha chini.'],
   photo:'Image prompt: photorealistic overhead flat lay on a light oak table, open dark green gift box at top left, items in an even grid, every item separated, plain unbranded packaging, no text, no logos, no people. Items: box of sterile gauze swabs, stack of sterile adhesive island dressings, bottle of sterile saline solution, box of disposable gloves, roll of surgical paper tape, blister strips of white tablets, digital thermometer, folded aluminium walking stick, bottle of hand sanitiser, AM/PM pill box, rolled non-slip bath mat, pack of large wet wipes, mosquito repellent roll-on, small box of tea bags',
   items:[R_GAUZE(30),R_DRESS(7),
    {k:'saline',g:'wound',n:['Sterile saline for cleaning the wound','Maji tasa ya chumvi ya kusafishia jeraha'],f:'m',q:['500 ml','Mililita 500'],src:['nice_ssi'],
     exp:['NICE recommends sterile saline for wound cleansing up to 48 hours after surgery, and many wounds sent home early, or with a drain or pin site, still need it beyond that; after 48 hours a shower with clean water is usually allowed. About 30–50 ml is used per clean, so one 500 ml bottle covers the first two weeks once opened and kept closed and clean. Antiseptics such as hydrogen peroxide or spirit are left out because they damage healing tissue.',
         'NICE inapendekeza maji tasa ya chumvi kusafishia jeraha hadi saa 48 baada ya upasuaji, na majeraha mengi yanayorudishwa nyumbani mapema, au yenye bomba au pini, bado huyahitaji baada ya hapo; baada ya saa 48 kuoga kwa maji safi kwa kawaida huruhusiwa. Takriban ml 30–50 hutumika kila kusafisha, hivyo chupa moja ya ml 500 inatosha wiki mbili za kwanza ikifungwa vizuri na kuwekwa safi. Dawa kama haidrojeni peroksaidi au spiriti hazijawekwa kwa sababu huharibu tishu zinazopona.'],
     o:{E:[[['sn_sal_e',500]]],C:[[['sn_sal_e',500]]],L:[[['sn_sal_n',177],['sn_sal_e',500]]]}},
    R_GLOVE(50),
    {k:'tape',g:'wound',n:['Surgical tape','Plasta ya upasuaji'],f:'m',q:['1 roll','Roli 1'],src:['nice_ssi'],
     exp:['Paper surgical tape holds gauze over a drain site or pin, or reinforces a dressing edge that lifts, and is gentle enough to remove from older or thin skin without tearing it. One roll lasts the full six weeks for most people. Fabric plasters are offered as the alternative for small puncture or cannula sites, which need covering for a day or two.'+' The tape is the same in every edition, because 3M Micropore is already the hospital standard for fragile skin.',
         'Plasta ya karatasi ya upasuaji hushikilia shashi juu ya sehemu ya bomba au pini, au huimarisha ukingo wa bandeji unaoinuka, na ni laini kiasi cha kuondolewa kwenye ngozi nyembamba ya mzee bila kuichana. Roli moja hudumu wiki zote sita kwa watu wengi. Plasta za kitambaa ni mbadala kwa matundu madogo ya sindano au kanula, yanayohitaji kufunikwa kwa siku moja au mbili.'+' Plasta hii ni sawa katika kila toleo, kwa sababu 3M Micropore tayari ndiyo kiwango cha hospitali kwa ngozi nyembamba.'],
     o:{E:[[['sn_tape',1]],[['sn_plast',10]]],C:[[['sn_tape',1]]],L:[[['sn_tape',1]]]}},
    R_PARA(100),
    {k:'therm',g:'wound',n:['Digital thermometer','Kipimajoto cha kidijitali'],f:'o',q:['1, once','1, mara moja'],src:['nice_ssi'],
     exp:['Fever, together with a wound that becomes red, hot, swollen or starts to discharge, is the earliest sign of surgical-site infection and the main reason to call the clinic early. Taking the temperature morning and evening in the first two weeks turns a vague feeling of being unwell into a number the nurse can act on. A digital thermometer gives a reading in under a minute and lasts for years.',
         'Homa, pamoja na jeraha linalokuwa jekundu, la moto, lililovimba au linaloanza kutoa usaha, ndiyo dalili ya mapema zaidi ya maambukizi ya jeraha la upasuaji na sababu kuu ya kupiga simu kliniki mapema. Kupima joto asubuhi na jioni katika wiki mbili za kwanza hubadilisha hisia ya kutojisikia vizuri kuwa namba ambayo muuguzi anaweza kuifanyia kazi. Kipimajoto cha kidijitali husoma chini ya dakika moja na hudumu miaka mingi.'],
     o:{E:[[['th_mic',1]],[['th_and',1]]],C:[[['th_and',1]]],L:[[['th_ir',1]],[['th_and',1]]]}},
    {k:'aid',g:'mob',n:['Walking aid, fitted at delivery','Kifaa cha kutembelea, kinapimwa kikiletwa'],f:'o',q:['1, once','1, mara moja'],src:['wfg','nice_str','who_rehab'],
     exp:['Which aid depends on the injury: a stick for one-sided weakness or a painful hip, a pair of crutches when a leg cannot take full weight after a fracture, and a wheeled frame after a stroke or major surgery where balance is poor. The default is a foldable stick; the choice switches to crutches or a frame on the discharge advice, and every aid is set to the person’s height at delivery. The stroke rehabilitation guideline stresses early, safe walking practice, and a wrong-height aid causes falls rather than preventing them.',
         'Kifaa kinategemea jeraha: fimbo kwa udhaifu wa upande mmoja au nyonga inayouma, magongo jozi moja mguu usipoweza kubeba uzito wote baada ya kuvunjika, na fremu yenye magurudumu baada ya kiharusi au upasuaji mkubwa ambapo mizani ni dhaifu. Chaguo la kawaida ni fimbo inayokunjika; hubadilishwa kuwa magongo au fremu kulingana na ushauri wa hospitali, na kila kifaa hupimwa kwa urefu wa mtu kinapoletwa. Mwongozo wa kurejesha uwezo baada ya kiharusi unasisitiza kuanza kutembea mapema na kwa usalama, na kifaa chenye urefu usio sahihi husababisha kuanguka badala ya kuzuia.'],
     o:{E:[[['sn_stk_f',1]],[['sn_cr_u',1]]],C:[[['sn_stk_l',1]],[['sn_cr_e',1]]],L:[[['sn_frame',1]],[['sn_stk_q',1]],[['sn_cr_e',1]]]}},
    R_RUB('m'),
    {k:'pill',g:'mob',n:['Pill organiser for discharge medicines','Kisanduku cha kupangia dawa za kuruhusiwa'],f:'o',q:['1, once','1, mara moja'],src:['wfg'],
     exp:['People often leave hospital with new medicines added to old ones, such as blood thinners after surgery or a stroke, antibiotics, and blood-pressure tablets, and confusion in the first weeks is a common cause of re-admission. A morning and evening organiser filled from the discharge sheet makes each dose visible to the family. It stays in use long after recovery.',
         'Mara nyingi watu hutoka hospitali na dawa mpya zilizoongezwa juu ya za zamani, kama dawa za kuyeyusha damu baada ya upasuaji au kiharusi, antibiotiki na dawa za presha, na kuchanganyikiwa katika wiki za kwanza ni chanzo cha kawaida cha kurudi hospitali. Kisanduku cha asubuhi na jioni kinachojazwa kutoka karatasi ya kuruhusiwa hufanya kila dozi ionekane kwa familia. Huendelea kutumika muda mrefu baada ya kupona.'],
     o:{E:[[['sn_pill_d',1]],[['sn_pill_w',1]]],C:[[['sn_pill_w',1]]],L:[[['sn_pill_p',1]]]}},
    {...MAT,g:'mob'},R_REP,
    {k:'wipes',g:'care',n:['Body wipes for washing in bed','Vitambaa vya kujisafisha kitandani'],f:'m',q:['72 wipes','Vitambaa 72'],src:['nice_ssi'],
     exp:['Until the wound may be showered, often 48 hours or more and longer with a cast or after a stroke, a daily wash in bed keeps skin clean and the person comfortable. Large adult body wipes do this without carrying water to the bed or wetting the dressing. Two to three wipes a day across the first fortnight comes to about one pack.',
         'Hadi jeraha litakaporuhusiwa kuoshwa, mara nyingi saa 48 au zaidi, na muda mrefu zaidi ukiwa na hogo au baada ya kiharusi, kujisafisha kitandani kila siku huweka ngozi safi na mtu akiwa na faraja. Vitambaa vikubwa vya watu wazima hufanya hivyo bila kubeba maji hadi kitandani wala kulowesha bandeji. Vitambaa viwili au vitatu kwa siku kwa wiki mbili ni takriban pakiti moja.'],
     o:{E:[[['sn_wip_v',72]],[['w_ang',72]]],C:[[['sn_wip_v',72]]],L:[[['w_hug',72]],[['sn_wip_v',72]]]}},
    {k:'lip',g:'care',n:['Lip balm','Mafuta ya midomo'],f:'o',q:['1 tin','Kopo 1'],src:['aadlips'],exp:['Anaesthesia, oxygen, fasting before surgery and dry hospital air leave most patients with parched, cracked lips, and painkillers and less drinking in the first days at home keep them dry. A plain petrolatum balm applied several times a day protects the lips while fluids and appetite recover. Camphor, menthol and flavoured balms are avoided because they sting split lips. One 20 g tin covers the whole six weeks of recovery, so it is sent once, in the first box.','Nusukaputi, oksijeni, kufunga kula kabla ya upasuaji na hewa kavu ya hospitali huwaacha wagonjwa wengi na midomo mikavu iliyopasuka, na dawa za maumivu pamoja na kunywa kidogo katika siku za kwanza nyumbani huiweka kavu. Mafuta ya kawaida ya petroli jeli yakipakwa mara kadhaa kwa siku hulinda midomo wakati maji mwilini na hamu ya kula vinarudi. Kafuri, menthol na mafuta yenye ladha huepukwa kwa sababu huuma midomo iliyopasuka. Kopo moja la gramu 20 linatosha wiki zote sita za kupona, hivyo hutumwa mara moja, katika sanduku la kwanza.'],o:{E:[[['mb_lbv',1]],[['mb_lbh',1]]],C:[[['mb_lbn',1]],[['mb_lbv',1]]],L:[[['mb_lbs',1]],[['mb_lbv',1]]]}},
    {k:'zawadi',g:'zawadi',n:['Zawadi: tea for the resting days','Zawadi: chai kwa siku za kupumzika'],f:'o',q:['1 box, once','Boksi 1, mara moja'],src:['who_rehab'],
     exp:['Many people drink too little in the first weeks home, because getting up hurts and appetite is low, and that slows healing and worsens the constipation that painkillers and bed rest already cause. A box of tea makes the next warm drink easy and is a small sign that the family is with them. Essential offers Tanzanian Kilimanjaro green tea or caffeine-free rooibos; Comfort sends both; Luxury pairs rooibos with a Bath & Body Works shea body cream. It is a comfort, not a clinical item, priced so it takes nothing away from wound care.',
         'Watu wengi hunywa maji kidogo katika wiki za kwanza nyumbani, kwa sababu kuamka kunauma na hamu ya kula iko chini, na hilo huchelewesha kupona na huzidisha choo kigumu ambacho dawa za maumivu na kulala kitandani tayari husababisha. Boksi la chai hurahisisha kinywaji kingine cha moto na ni ishara ndogo kwamba familia iko pamoja naye. Toleo la Msingi linatoa chai ya kijani ya Kilimanjaro ya Tanzania au chai ya rooibos isiyo na kafeini; Comfort hutuma zote mbili; Luxury huunganisha rooibos na krimu ya mwili ya shea ya Bath & Body Works. Ni faraja, si kifaa cha matibabu, na bei yake haipunguzi chochote katika huduma ya jeraha.'],
     o:{E:[[['cd_gtk',25]],[['cd_rbk',20]]],C:[[['cd_gtk',25],['cd_rbk',20]]],L:[[['cd_rbk',20],['bbw_bc',226]],[['cd_gtk',25],['cd_rbk',20]]]}}]},
  {k:'weeks3-6',n:['Weeks 3–6','Wiki 3–6'],d:['Rehabilitation and strength','Mazoezi na kurejesha nguvu'],m:1,
   intro:['From the third week the wound is usually closed and the work becomes rebuilding strength, circulation and weight lost in hospital. NICE stroke rehabilitation guidance recommends daily, progressive practice of the movements a person wants back, and the same principle applies after a fracture or joint surgery. Reduced mobility keeps the risk of blood clots raised for weeks after discharge, so compression is included where the clinician advises it, together with protein-energy support for appetites that have not yet returned.',
          'Kuanzia wiki ya tatu jeraha kwa kawaida limefunga na kazi inakuwa kujenga upya nguvu, mzunguko wa damu na uzito uliopotea hospitalini. Mwongozo wa NICE wa kurejesha uwezo baada ya kiharusi unapendekeza mazoezi ya kila siku yanayoongezeka ya miondoko ambayo mtu anataka kuirejesha, na kanuni hiyo hiyo inafaa baada ya kuvunjika au upasuaji wa kiungo. Kutotembea vya kutosha huweka hatari ya damu kuganda juu kwa wiki kadhaa baada ya kuruhusiwa, hivyo soksi za mgandamizo zimewekwa pale daktari anaposhauri, pamoja na lishe ya protini na nishati kwa wale ambao hamu ya kula bado haijarudi.'],
   photo:'Image prompt: photorealistic overhead flat lay on a light oak table, open dark green gift box at top left, items in an even grid, every item separated, plain unbranded packaging, no text, no logos, no people. Items: set of five coloured exercise loop bands, pair of beige compression stockings, two tins of nutritional shake powder, blister strips of white tablets, small stack of sterile adhesive dressings, small box of sterile gauze swabs, box of disposable gloves, white pump bottle of body lotion, bottle of hand sanitiser, mosquito repellent roll-on, bottle of shower gel',
   items:[
    {k:'band',g:'rehab',n:['Resistance band set for home exercise','Mikanda ya mazoezi ya nyumbani'],f:'o',q:['1 set, once','Seti 1, mara moja'],src:['nice_str','coch_ex','who_rehab'],
     exp:['Muscle is lost fast in hospital, about 1% a day of bed rest in older adults, and strength comes back only through progressive loading. Five graded bands let the physiotherapist prescribe hip, knee, shoulder and grip exercises that step up as the person gets stronger, which is the progressive practice NICE recommends after stroke. Comfort and Luxury add a seated pedal exerciser for daily circulation and leg work before walking outside is safe.',
         'Misuli hupotea haraka hospitalini, takriban asilimia 1 kwa siku ya kulala kitandani kwa wazee, na nguvu hurudi tu kwa kuongeza uzito wa mazoezi hatua kwa hatua. Mikanda mitano ya viwango tofauti humwezesha mtaalamu wa viungo kuagiza mazoezi ya nyonga, goti, bega na kushika yanayoongezeka kadiri mtu anavyopata nguvu, ndiyo mazoezi ya kuongezeka ambayo NICE inapendekeza baada ya kiharusi. Comfort na Luxury huongeza baiskeli ndogo ya kukaa kwa mzunguko wa damu na mazoezi ya miguu kabla ya kutembea nje kuwa salama.'],
     o:{E:[[['sn_band',1]]],C:[[['sn_band',1],['sn_ped',1]]],L:[[['sn_band',1],['sn_ped',1]]]}},
    {k:'comp',g:'rehab',n:['Compression stockings (when advised)','Soksi za mgandamizo (zikishauriwa)'],f:'o',q:['1 pair, once','Jozi 1, mara moja'],src:['nice_vte'],
     exp:['After hip, knee or abdominal surgery, a fracture or a stroke, reduced movement keeps the risk of deep-vein thrombosis raised for weeks, and NICE uses mechanical prophylaxis alongside medicines for people at risk. Graduated stockings support the calf pump while walking is still limited. They are supplied only when the surgeon or physiotherapist advises them, measured at the ankle and calf, and never used with poor leg circulation or open leg wounds.',
         'Baada ya upasuaji wa nyonga, goti au tumbo, kuvunjika au kiharusi, kutembea kidogo huweka hatari ya damu kuganda kwenye mishipa ya miguu juu kwa wiki kadhaa, na NICE hutumia kinga ya mgandamizo pamoja na dawa kwa walio hatarini. Soksi za mgandamizo husaidia misuli ya ndama kusukuma damu wakati kutembea bado ni kidogo. Hutolewa tu daktari wa upasuaji au mtaalamu wa viungo anaposhauri, hupimwa kwenye kifundo na ndama, na hazitumiki kamwe kwa wenye mzunguko duni wa damu miguuni au vidonda vya mguu.'],
     o:{E:[[['sn_cmp_b',1]],[['cmp',1]]],C:[[['cmp',1]]],L:[[['sn_cmp_t',1]]]}},
    {k:'nutri',g:'nutri',n:['Oral nutrition supplement','Kinywaji cha lishe ya ziada'],f:'m',q:['2 tins (800 g)','Makopo 2 (gramu 800)'],src:['coch_ons','who_rehab'],
     exp:['Healing tissue and rebuilding muscle need more protein and energy than most people eat in the weeks after hospital, when appetite is low. The Cochrane review found protein-energy supplements improve weight and reduce complications in undernourished older people. Two 400 g tins hold about 15 servings of 53 g (four scoops): one fortified drink every second day through weeks 3–6, taken between meals so they add to food rather than replace it.',
         'Tishu zinazopona na misuli inayojengwa upya huhitaji protini na nishati zaidi kuliko watu wengi wanavyokula katika wiki baada ya hospitali, wakati hamu ya kula iko chini. Tathmini ya Cochrane ilionyesha virutubisho vya protini na nishati huongeza uzito na hupunguza matatizo kwa wazee wenye utapiamlo. Makopo mawili ya gramu 400 yana takriban vipimo 15 vya gramu 53 (vijiko vinne): kinywaji kimoja chenye virutubisho kila siku ya pili katika wiki ya 3–6, hunywewa kati ya milo ili kuongeza chakula si kukibadilisha.'],
     o:{E:[[['sn_rep',800]],[['sn_ens',800]]],C:[[['sn_ens',800]]],L:[[['sn_ens',800]]]}},
    R_PARA(50),R_DRESS(4),R_GAUZE(20),R_GLOVE(20),R_RUB('q'),R_REP,
    {k:'lotion',g:'care',n:['Body moisturiser','Losheni ya mwili'],f:'q',q:['200 ml for the period','Mililita 200 kwa kipindi'],src:['nice_pu','coch_iad'],
     exp:['Skin under casts, splints and stockings dries and itches, and a healed scar is softer and less tight when it is massaged daily with a plain moisturiser once the wound has fully closed. A small daily amount on the legs and scar area uses about 200 ml over weeks 3–6. Perfume-free products are chosen so nothing irritates the new skin.',
         'Ngozi iliyo chini ya hogo, banzi na soksi za mgandamizo hukauka na kuwasha, na kovu lililopona huwa laini na lisilobana likisuguliwa kila siku kwa losheni ya kawaida baada ya jeraha kufunga kabisa. Kiasi kidogo kila siku miguuni na kwenye kovu hutumia takriban ml 200 katika wiki ya 3–6. Losheni zisizo na manukato zimechaguliwa ili kitu kisiwashe ngozi mpya.'],
     o:{E:[[['sn_lot_n',200]],[['sn_lot_nn',200]]],C:[[['sn_lot_eu',200]]],L:[[['sn_lot_ce',200]]]}},
    {k:'zawadi',g:'zawadi',n:['Zawadi: a first-shower treat','Zawadi: zawadi ya kuoga kwa mara ya kwanza'],f:'o',q:['1, once','1, mara moja'],src:['who_rehab'],
     exp:['The first proper shower after weeks of bed washes is a milestone in recovery, and marking it helps morale, which itself predicts how well people keep up rehabilitation. A fragranced shower gel is kept for this moment, for use on skin away from the healed wound. Luxury gives a Bath & Body Works shower gel; Essential a rich cocoa body lotion to follow the shower.'+' Comfort gives a Nivea shower gel.',
         'Kuoga vizuri kwa mara ya kwanza baada ya wiki za kujisafisha kitandani ni hatua muhimu ya kupona, na kuisherehekea huinua ari, ambayo yenyewe hutabiri jinsi mtu atakavyoendelea na mazoezi. Sabuni ya maji yenye harufu nzuri imewekwa kwa wakati huu, itumike kwenye ngozi iliyo mbali na jeraha lililopona. Luxury hutoa sabuni ya Bath & Body Works; Essential hutoa losheni ya kakao ya kupaka baada ya kuoga.'+' Faraja hutoa sabuni ya kuogea ya Nivea.'],
     o:{E:[[['bl_vas',400]],[['ms_det',300]]],C:[[['sg_nsg',250]],[['bl_vas',400]]],L:[[['bbw_sg',295]],[['bbw_bc',226]]]}}]}
 ],
 svc:[
  {t:['Days 2–3','Siku 2–3'],n:['Nurse home visit: wound, medicines, pain','Ziara ya muuguzi nyumbani: jeraha, dawa, maumivu'],w:'partner',p:40000,why:['Early review catches surgical-site infection before it needs re-admission.','Ukaguzi wa mapema hugundua maambukizi kabla ya kuhitaji kulazwa tena.'],src:['nice_ssi']},
  {t:['Twice a week, weeks 1–6','Mara mbili kwa wiki, wiki 1–6'],n:['Home physiotherapy session','Kipindi cha tiba ya viungo nyumbani'],w:'partner',p:35000,why:['Daily progressive practice is the core of stroke and fracture rehabilitation.','Mazoezi ya kila siku yanayoongezeka ndiyo kiini cha kurejesha uwezo.'],src:['nice_str','who_rehab']},
  {t:['Days 10–14','Siku 10–14'],n:['Stitch or clip removal','Kutoa nyuzi au klipu'],w:'quote',why:['Booked with the operating clinic or a partner nurse.','Hupangwa na kliniki iliyofanya upasuaji au muuguzi mshirika.'],src:['nice_ssi']},
  {t:['Weekly','Kila wiki'],n:['Temperature, wound photo and pain check-in','Kufuatilia joto, picha ya jeraha na maumivu'],w:'store',why:['Fever with a red, hot wound is the earliest sign of infection.','Homa na jeraha jekundu la moto ni dalili ya mapema ya maambukizi.'],src:['nice_ssi']},
  {t:['Week 6','Wiki ya 6'],n:['Blood pressure, sugar and weight check','Kipimo cha presha, sukari na uzito'],w:'store',why:['Only 17.6% of hypertensive Tanzanians are diagnosed; stroke recovery depends on control.','Ni 17.6% tu ya Watanzania wenye presha waliogunduliwa; kupona kiharusi hutegemea udhibiti.'],src:['who_htz','nice_str']},
  {t:['Optional','Hiari'],n:['Commode chair or wheelchair supply','Kiti cha choo au kiti cha magurudumu'],w:'quote',why:['For people who cannot yet reach the toilet safely.','Kwa wasioweza bado kufika chooni kwa usalama.'],src:['wfg']}
 ],
 lux:{brands:['Primapore','NeilMed','Panadol','Ensure','Tynor','Cetaphil','Bath & Body Works'],
  text:['Luxury uses Opsite Post-Op showerproof dressings with NeilMed sterile wound wash, Panadol, Ensure and mid-thigh Tynor compression, with a wheeled walking frame or elbow crutches as the walking aid. The recovery gift becomes Bath & Body Works.',
        'Toleo la Luxury hutumia bandeji za Opsite Post-Op zisizopitisha maji pamoja na maji tasa ya NeilMed, Panadol, Ensure na soksi za Tynor za hadi pajani, na fremu yenye magurudumu au magongo ya kiwiko kama kifaa cha kutembelea. Zawadi ya kupona inakuwa ya Bath & Body Works.']}
};
window.AFYAMB_ADD(rec);
