const LS=D.LISHE;if(LS)LS.items.forEach(i=>{const id='ls_'+i.k;if(!D.B[id])D.B[id]=[i.n[0],i.pack,1,i.tzs,i.status,i.url,i.cost||'brand','pack']});
const UJI=(kg,who)=>({k:'uji',n:who.n,f:'m',q:[kg+' kg a month',kg.toString().replace('.',',')+' kg kwa mwezi'],src:who.src,exp:who.exp,o:{M:who.o(kg)}});
const MUM={n:['Fortified porridge flour for mum','Unga wa uji wenye virutubisho kwa mama'],src:['tdhs22','livgoods'],exp:['One large cup of uji a day, about 50 g of fortified flour, adds energy, protein, iron and B vitamins at the time a mother needs them most, in pregnancy and while breastfeeding, when anaemia and tiredness are common. 50 g a day is 1.5 kg a month. It is food the family already buys, delivered at a lower price.','Kikombe kikubwa kimoja cha uji kwa siku, takriban gramu 50 za unga wenye virutubisho, huongeza nguvu, protini, madini ya chuma na vitamini B wakati mama anapozihitaji zaidi, wakati wa ujauzito na kunyonyesha, ambapo upungufu wa damu na uchovu ni jambo la kawaida. Gramu 50 kwa siku ni kilo 1.5 kwa mwezi. Ni chakula ambacho familia tayari inanunua, kinacholetwa kwa bei nafuu zaidi.'],o:kg=>[[['ls_uji_famila_nutri',kg]],[['ls_uji_eq_afya',kg]],[['ls_uji_jogoo_maize',kg/2]]]};
const BABY={n:['Fortified baby porridge, from 6 months','Uji wa mtoto wenye virutubisho, kuanzia miezi 6'],src:['tdhs22','who_cf'],exp:['From six months breast milk alone no longer covers a baby’s iron and energy needs, and 30% of Tanzanian children under five are stunted. A thick fortified porridge two to three times a day, about 35 g of flour, alongside breastfeeding and family foods, is 1 kg a month. Make it thick enough to stay on the spoon.','Kuanzia miezi sita maziwa ya mama pekee hayatoshelezi tena mahitaji ya madini ya chuma na nguvu ya mtoto, na asilimia 30 ya watoto wa Tanzania walio chini ya miaka mitano wamedumaa. Uji mzito wenye virutubisho mara mbili hadi tatu kwa siku, takriban gramu 35 za unga, pamoja na kunyonyesha na chakula cha familia, ni kilo 1 kwa mwezi. Upike mzito kiasi cha kukaa kwenye kijiko.'],o:kg=>[[['ls_cer_famila_baby',kg]],[['ls_cer_famila_wean',kg]],[['ls_uji_famila_nutri',kg]]]};
const TOD={n:['Fortified porridge flour for the child','Unga wa uji wenye virutubisho kwa mtoto'],src:['tdhs22'],exp:['A toddler eats three to four meals a day, and a cup of fortified uji, about 50 g of flour, is the cheapest way to add iron, zinc and vitamins against stunting, which affects 30% of Tanzanian children under five. 50 g a day is 1.5 kg a month.','Mtoto mdogo hula milo mitatu hadi minne kwa siku, na kikombe cha uji wenye virutubisho, takriban gramu 50 za unga, ndiyo njia nafuu zaidi ya kuongeza madini ya chuma, zinki na vitamini dhidi ya udumavu, unaowapata asilimia 30 ya watoto wa Tanzania walio chini ya miaka mitano. Gramu 50 kwa siku ni kilo 1.5 kwa mwezi.'],o:MUM.o};
const SCH={n:['Fortified porridge flour for school mornings','Unga wa uji wenye virutubisho kwa asubuhi za shule'],src:['tdhs22'],exp:['A cup of fortified uji before school, about 40 g of flour on 22 school days, is about 1 kg a month. A child who has eaten concentrates better, and the fortified flour adds iron and B vitamins.','Kikombe cha uji wenye virutubisho kabla ya shule, takriban gramu 40 za unga kwa siku 22 za shule, ni takriban kilo 1 kwa mwezi. Mtoto aliyekula huwa makini zaidi darasani, na unga wenye virutubisho huongeza madini ya chuma na vitamini B.'],o:MUM.o};
const WATER=g=>({k:'water',g,n:['Drinking-water treatment','Dawa ya kutibu maji ya kunywa'],f:'m',q:['1 bottle a month','Chupa 1 kwa mwezi'],src:['unicefwash','tdhs22'],exp:['Only about one Tanzanian in five treats drinking water properly, and 9% of children under five had diarrhoea in the two weeks before the 2022 survey. One capful in 20 litres, left 30 minutes, makes water safe to drink; one bottle covers a small family’s drinking water for the month.','Ni takriban Mtanzania mmoja kati ya watano tu anayetibu maji ya kunywa ipasavyo, na asilimia 9 ya watoto walio chini ya miaka mitano waliharisha katika wiki mbili kabla ya utafiti wa 2022. Kifuniko kimoja kwenye lita 20, kikisubiri dakika 30, hufanya maji kuwa salama kunywa; chupa moja inatosha maji ya kunywa ya familia ndogo kwa mwezi.'],o:{M:[[['h_aqg',1]],[['mb_wg',1]],[['mb_aqt',25]]]}});
