function css(){if(document.getElementById('p38-css'))return;const e=document.createElement('style');e.id='p38-css';e.textContent=CSS+CSS2;document.head.appendChild(e)}
const SRCK=Object.keys(R);const cite=k=>{const i=SRCK.indexOf(k);return i<0?'':`<a class="cite" href="${R[k][1]}" target="_blank" rel="noopener" title="${E(R[k][0])}">[${i+1}]</a>`};
const S={pk:'mama',sk:null,tier:'E',plan:12,tab:'box',ch:{},x:{},hh:{b:['mama','aid','home'],t:'E',p:12},ls:{cat:'all',cart:{}},sim:{n:5000,mix:'all',ed:[60,30,10],pl:[20,30,50],sv:40,ls:30,lb:40000,ms:20}};
